# Created by OpenAI
"""Three-launch, runtime-routed Qwen FP8 MoE decode for AMD MI355.

M=16 loads W13 directly in folded-MFMA operand ownership. Other shapes retain
the inherited load and scheduling policies. Routing and scratch are invocation-
local; launch boundaries and all numerical rounding points are preserved.
"""
from dataclasses import dataclass

import torch
from triton.language.core import range as _loop_range
from triton.experimental import gluon
from triton.experimental.gluon import language as gl


@dataclass(frozen=True)
class _PrecisionConfig:
    dtype: object = torch.float8_e4m3fn
    max_finite: float = 448.0
    group_quant_max: float = 448.0


@gluon.jit
def _folded_fp8_dot(weight, q_transposed, BN: gl.constexpr, NW: gl.constexpr):
    mma: gl.constexpr = gl.amd.AMDMFMALayout(
        version=4, instr_shape=[16, 16, 128], transposed=True,
        warps_per_cta=[NW, 1], tiles_per_warp=[BN // 16, 1])
    a = gl.convert_layout(weight.reshape((16 * BN, 128)), gl.DotOperandLayout(0, mma, 16))
    b = gl.convert_layout(q_transposed, gl.DotOperandLayout(1, mma, 16))
    dot = gl.amd.cdna4.mfma_scaled(a, None, 'e4m3', b, None, 'e4m3',
                                  gl.zeros((16 * BN, 16), gl.float32, mma))
    row = gl.arange(0, 16 * BN, gl.SliceLayout(1, mma))
    diagonal = gl.gather(dot, (row // BN)[:, None], 1)
    return diagonal.reshape((16, BN))


@gluon.jit
def _native_fp8_dot(weight, q, BN: gl.constexpr, NW: gl.constexpr):
    # Preserve the four ordered native K=32 accumulations.
    mma: gl.constexpr = gl.amd.AMDMFMALayout(
        version=4, instr_shape=[16, 16, 32], transposed=True,
        warps_per_cta=[NW, 1, 1])
    a = gl.convert_layout(weight, gl.DotOperandLayout(0, mma, 16))
    b = gl.convert_layout(q, gl.SliceLayout(2, gl.DotOperandLayout(1, mma, 16)))[:, :, None]
    dot = gl.amd.cdna3.mfma(a, b, gl.zeros((16, BN, 1), gl.float32, mma))
    return gl.sum(dot, 2)


@gluon.jit
def _column(x, index: gl.constexpr):
    width: gl.constexpr = x.shape[-1]
    if width == 2:
        a, b = gl.split(x)
        if index == 0:
            return a
        else:
            return b
    else:
        a, b = gl.split(x.reshape((x.shape[0], width // 2, 2)))
        if index % 2 == 0:
            return _column(a, index // 2)
        else:
            return _column(b, index // 2)


@gluon.jit
def _reciprocal(x):
    r = gl.inline_asm_elementwise("v_rcp_f32 $0, $1", "=v,v", [x],
                                 dtype=gl.float32, is_pure=True, pack=1)
    r = gl.fma(r, gl.fma(-x, r, 1.0), r)
    return gl.where(x == float('inf'), 0.0, r)


@gluon.jit
def _divide(x, scale, REFINE: gl.constexpr = True):
    if REFINE:
        r = _reciprocal(scale)
    else:
        r = gl.inline_asm_elementwise("v_rcp_f32 $0, $1", "=v,v", [scale],
                                     dtype=gl.float32, is_pure=True, pack=1)
    value = x * r
    error = gl.fma(-value, scale, x)
    return gl.fma(error, r, value)


@gluon.jit
def _sigmoid(x, FAST_EXP: gl.constexpr = False):
    if FAST_EXP:
        exponent = x * -1.4426950408889634
        exp_value = gl.inline_asm_elementwise(
            "v_exp_f32 $0, $1", "=v,v", [exponent],
            dtype=gl.float32, is_pure=True, pack=1)
    else:
        exp_value = gl.exp(-x)
    return _reciprocal((1.0 + exp_value) * (2.0 ** -8)) * (2.0 ** -8)


@gluon.jit
def _encode_logit(value, expert):
    bits = value.to(gl.bfloat16).to(gl.uint16, bitcast=True).to(gl.uint32)
    bits = gl.where(value == 0, 0, bits)
    ordered = gl.where((bits & 32768) != 0, bits ^ 65535, bits ^ 32768)
    return (ordered << 9) | (511 - expert).to(gl.uint32)


@gluon.jit
def _decode_logit(key):
    ordered = key >> 9
    bits = gl.where((ordered & 32768) != 0, ordered ^ 32768, ordered ^ 65535)
    return bits.to(gl.uint16).to(gl.bfloat16, bitcast=True).to(gl.float32)


@gluon.jit
def _router_partial(H, R, Keys, pid, M: gl.constexpr, RN: gl.constexpr,
                    RSPLIT: gl.constexpr, NW: gl.constexpr):
    part = pid // (512 // RN)
    tile = pid % (512 // RN)
    groups: gl.constexpr = 16 // RSPLIT
    layout: gl.constexpr = gl.BlockedLayout([1, 1, 4], [1, 4, 16], [NW, 1, 1], [2, 1, 0])
    gi = gl.arange(0, groups, gl.SliceLayout(1, gl.SliceLayout(2, layout)))
    ni = tile * RN + gl.arange(0, RN, gl.SliceLayout(0, gl.SliceLayout(2, layout)))
    ki = gl.arange(0, 128, gl.SliceLayout(0, gl.SliceLayout(1, layout)))
    w = gl.load(R + ni[None, :, None] * 2048 + (part * groups + gi[:, None, None]) * 128 + ki[None, None, :])
    mi = gl.arange(0, 16, gl.SliceLayout(0, gl.SliceLayout(2, layout)))
    h = gl.load(H + mi[None, :, None] * 2048 + (part * groups + gi[:, None, None]) * 128 + ki[None, None, :],
                mi[None, :, None] < M, other=0.0)
    mma: gl.constexpr = gl.amd.AMDMFMALayout(
        version=4, instr_shape=[16, 16, 32], transposed=True,
        warps_per_cta=[NW, 1, 1])
    a = gl.convert_layout(w, gl.DotOperandLayout(0, mma, 8))
    b = gl.convert_layout(h.permute((0, 2, 1)), gl.DotOperandLayout(1, mma, 8))
    acc = gl.amd.cdna3.mfma(a, b, gl.zeros((groups, RN, 16), gl.float32, mma))
    value = gl.sum(acc, 0).trans()
    store_layout: gl.constexpr = gl.BlockedLayout([1, 2], [4, 16], [NW, 1], [1, 0])
    value = gl.convert_layout(value, store_layout)
    om = gl.arange(0, 16, gl.SliceLayout(1, store_layout))
    on = tile * RN + gl.arange(0, RN, gl.SliceLayout(0, store_layout))
    gl.store(Keys + part * M * 512 + om[:, None] * 512 + on[None, :], value, om[:, None] < M)


@gluon.jit
def _prepare(H, R, SG, Keys, Q, QS, Shared, M: gl.constexpr,
             RN: gl.constexpr, NW: gl.constexpr, RSPLIT: gl.constexpr,
             PREP_FIRST: gl.constexpr = True, GATE_FIRST: gl.constexpr = False,
             QUANT_LANES: gl.constexpr = 64, GATE_GROUPS: gl.constexpr = False,
             SORT_KEYS: gl.constexpr = False, UNSIGNED_PID: gl.constexpr = False,
             ROUTER_BUFFER: gl.constexpr = False):
    pid = gl.program_id(0)
    if UNSIGNED_PID:
        pid = pid.to(gl.uint32)
    router_ctas: gl.constexpr = (M if RSPLIT == 1 else RSPLIT) * (512 // RN)
    prep_ctas: gl.constexpr = M * 2
    if PREP_FIRST:
        pid = gl.where(pid < prep_ctas, pid + router_ctas, pid - prep_ctas)
    if GATE_FIRST:
        pid = gl.where(pid >= router_ctas,
                       router_ctas + (pid - router_ctas + M) % (2 * M), pid)
    if pid < router_ctas:
        if RSPLIT > 1:
            _router_partial(H, R, Keys, pid, M, RN, RSPLIT, NW)
        else:
            row = pid // (512 // RN)
            tile = pid % (512 // RN)
            layout: gl.constexpr = gl.BlockedLayout([1, 4], [1, 64], [NW, 1], [1, 0])
            n = tile * RN + gl.arange(0, RN, gl.SliceLayout(1, layout))
            k = gl.arange(0, 1024, gl.SliceLayout(0, layout))
            if ROUTER_BUFFER:
                w = gl.amd.cdna4.buffer_load(R.to(gl.pointer_type(gl.uint32)), n[:, None] * 1024 + k[None, :])
            else:
                w = gl.load(R.to(gl.pointer_type(gl.uint32)) + n[:, None] * 1024 + k[None, :])
            h = gl.load(H.to(gl.pointer_type(gl.uint32)) + row * 1024 + k)
            products = gl.inline_asm_elementwise(
                "v_dot2_f32_bf16 $0, $1, $2, $3", "=v,v,v,v",
                [w, h[None, :], 0.0], dtype=gl.float32, is_pure=True, pack=1)
            value = gl.sum(products, 1).to(gl.bfloat16)
            encoded = _encode_logit(value, n)
            if SORT_KEYS:
                gl.static_assert(RN == 4)
                sort_layout: gl.constexpr = gl.BlockedLayout([4], [64], [NW], [0])
                local_keys = gl.convert_layout(encoded, sort_layout).reshape((1, 4))
                a, b, c, d = _sort_four(_column(local_keys, 0), _column(local_keys, 1),
                                      _column(local_keys, 2), _column(local_keys, 3))
                sorted_keys = gl.join(gl.join(a, c), gl.join(b, d)).reshape((4,))
                sn = tile * 4 + gl.arange(0, 4, sort_layout)
                gl.store(Keys + row * 512 + sn, sorted_keys)
            else:
                gl.store(Keys + row * 512 + n, encoded)
    else:
        prep_row = (pid - router_ctas) % M
        if pid < router_ctas + M:
            prep_layout: gl.constexpr = gl.BlockedLayout([1, 2], [64 // QUANT_LANES, QUANT_LANES], [NW, 1], [1, 0])
            groups = gl.arange(0, 16, gl.SliceLayout(1, prep_layout))
            prep_k = gl.arange(0, 128, gl.SliceLayout(0, prep_layout))
            offsets = groups[:, None] * 128 + prep_k[None, :]
            prep_h = gl.load(H + prep_row * 2048 + offsets).to(gl.float32)
            maximum = gl.maximum(gl.max(gl.abs(prep_h), 1), 1.0e-10)
            scale = maximum / 448.0
            q = _divide(prep_h, scale[:, None]).to(Q.dtype.element_ty)
            gl.store(Q + prep_row * 2048 + offsets, q)
            gl.store(QS + prep_row * 16 + groups, scale)
        if pid >= router_ctas + M:
            if GATE_GROUPS:
                gate_layout: gl.constexpr = gl.BlockedLayout([1, 1], [1, 64], [NW, 1], [1, 0])
                group = gl.arange(0, 8, gl.SliceLayout(1, gate_layout))
                k = gl.arange(0, 256, gl.SliceLayout(0, gate_layout))
                t = group[:, None] * 256 + k[None, :]
                x = gl.load(H + prep_row * 2048 + t).to(gl.float32)
                prep_w = gl.load(SG + t).to(gl.float32)
                partials = gl.sum(x * prep_w, 1)
                local_layout: gl.constexpr = gl.BlockedLayout([8], [64], [NW], [0])
                partials = gl.convert_layout(partials, local_layout).reshape((1, 8))
            else:
                gate_layout: gl.constexpr = gl.BlockedLayout([1], [64], [NW], [0])
                t = gl.arange(0, 2048, gate_layout)
                x = gl.load(H + prep_row * 2048 + t).to(gl.float32)
                prep_w = gl.load(SG + t).to(gl.float32)
                partials = gl.sum((x * prep_w).reshape((8, 256)), 1).reshape((1, 8))
            total_vector = 0.0 + _column(partials, 0)
            for i in gl.static_range(1, 8):
                total_vector = total_vector + _column(partials, i)
            total = gl.sum(total_vector, 0)
            total = total.to(gl.bfloat16).to(gl.float32)
            coefficient = _sigmoid(total).to(gl.bfloat16).to(gl.float32)
            gl.store(Shared + prep_row, coefficient)


@gluon.jit
def _route_keys(Keys, row, NW: gl.constexpr, M: gl.constexpr, RSPLIT: gl.constexpr,
                KEY_PACK: gl.constexpr, KEY_BUFFER: gl.constexpr):
    layout: gl.constexpr = gl.SliceLayout(0, gl.BlockedLayout([1, KEY_PACK], [1, 64], [NW, 1], [1, 0]))
    n = gl.arange(0, 512, layout)
    if RSPLIT == 1:
        if KEY_BUFFER:
            return gl.amd.cdna4.buffer_load(Keys, row * 512 + n).to(gl.uint32)
        else:
            return gl.load(Keys + row * 512 + n).to(gl.uint32)
    else:
        logits = gl.full((512,), 0.0, gl.float32, layout)
        for part in gl.static_range(RSPLIT):
            logits += gl.load(Keys + part * M * 512 + row * 512 + n)
        return _encode_logit(logits.to(gl.bfloat16), n)


@gluon.jit
def _queue_compare(queue, left: gl.constexpr, right: gl.constexpr):
    high = gl.maximum(queue[left], queue[right])
    low = gl.minimum(queue[left], queue[right])
    result = ()
    for i in gl.static_range(8):
        if i == left:
            result += (high,)
        elif i == right:
            result += (low,)
        else:
            result += (queue[i],)
    return result


@gluon.jit
def _sort_four(a, b, c, d):
    high = gl.inline_asm_elementwise("v_max3_u32 $0, $1, $2, $3", "=v,v,v,v",
                                     [a, b, c], dtype=gl.uint32, is_pure=True, pack=1)
    middle = gl.inline_asm_elementwise("v_med3_u32 $0, $1, $2, $3", "=v,v,v,v",
                                       [a, b, c], dtype=gl.uint32, is_pure=True, pack=1)
    low = gl.inline_asm_elementwise("v_min3_u32 $0, $1, $2, $3", "=v,v,v,v",
                                    [a, b, c], dtype=gl.uint32, is_pure=True, pack=1)
    second = gl.inline_asm_elementwise("v_med3_u32 $0, $1, $2, $3", "=v,v,v,v",
                                       [high, middle, d], dtype=gl.uint32, is_pure=True, pack=1)
    third = gl.inline_asm_elementwise("v_med3_u32 $0, $1, $2, $3", "=v,v,v,v",
                                      [middle, low, d], dtype=gl.uint32, is_pure=True, pack=1)
    return gl.maximum(high, d), second, third, gl.minimum(low, d)


@gluon.jit
def _sorted_queue(keys, KEY_PACK: gl.constexpr, QUEUE_WIDTH: gl.constexpr = 8,
                  PRESORTED: gl.constexpr = False):
    local = keys.reshape((8 // KEY_PACK, 64, KEY_PACK)).permute((1, 0, 2)).reshape((64, 8))
    queue = ()
    for i in gl.static_range(8):
        queue += (_column(local, i),)
    if not PRESORTED:
        queue = (_sort_four(queue[0], queue[1], queue[2], queue[3])
                 + _sort_four(queue[4], queue[5], queue[6], queue[7]))
    if QUEUE_WIDTH == 8:
        pairs: gl.constexpr = ((0, 4), (2, 6), (2, 4), (1, 5), (3, 7),
                               (3, 5), (1, 2), (3, 4), (5, 6))
        for step in gl.static_range(9):
            queue = _queue_compare(queue, pairs[step][0], pairs[step][1])
    return queue


@gluon.jit
def _queue_head(queue, QUEUE_WIDTH: gl.constexpr):
    head = queue[0]
    for i in gl.static_range(QUEUE_WIDTH, 8, QUEUE_WIDTH):
        head = gl.maximum(head, queue[i])
    return gl.max(head, 0)


@gluon.jit
def _pop_queue(queue, QUEUE_WIDTH: gl.constexpr = 8):
    winner = _queue_head(queue, QUEUE_WIDTH)
    result = ()
    for i in gl.static_range(8):
        take = queue[(i // QUEUE_WIDTH) * QUEUE_WIDTH] == winner
        if (i + 1) % QUEUE_WIDTH == 0:
            result += (gl.where(take, 0, queue[i]),)
        else:
            result += (gl.where(take, queue[i + 1], queue[i]),)
    return winner, result


@gluon.jit
def _queue_rank(keys, rank, KEY_PACK: gl.constexpr, TOPK_UNROLL: gl.constexpr,
                QUEUE_WIDTH: gl.constexpr, PRESORTED: gl.constexpr):
    queue = _sorted_queue(keys, KEY_PACK, QUEUE_WIDTH, PRESORTED)
    for i in _loop_range(rank, loop_unroll_factor=TOPK_UNROLL):
        winner, queue = _pop_queue(queue, QUEUE_WIDTH)
    return _queue_head(queue, QUEUE_WIDTH)


@gluon.jit
def _select_route_key(keys, rank, EARLY: gl.constexpr, KEY_PACK: gl.constexpr,
                      TOPK_UNROLL: gl.constexpr, QUEUE_WIDTH: gl.constexpr,
                      PRESORTED: gl.constexpr):
    if EARLY == 0:
        return _queue_rank(keys, rank, KEY_PACK, TOPK_UNROLL, QUEUE_WIDTH, PRESORTED)
    else:
        if rank < EARLY:
            for i in _loop_range(rank, loop_unroll_factor=TOPK_UNROLL):
                winner = gl.max(keys, 0)
                keys = gl.where(keys == winner, 0, keys)
            return gl.max(keys, 0)
        else:
            return _queue_rank(keys, rank, KEY_PACK, TOPK_UNROLL, QUEUE_WIDTH, PRESORTED)


@gluon.jit
def _project(Keys, Q, QS, Shared, W, WS, Packed, Ids, Probs,
             M: gl.constexpr, BN: gl.constexpr, NW: gl.constexpr,
             RSPLIT: gl.constexpr, BUFFER: gl.constexpr, EARLY: gl.constexpr,
             KEY_PACK: gl.constexpr, PREFETCH: gl.constexpr,
             REVERSE_RANK: gl.constexpr,
             KEY_BUFFER: gl.constexpr = False, Q_BUFFER: gl.constexpr = False,
             FUSE_ACT: gl.constexpr = False, TOPK_UNROLL: gl.constexpr = 0,
             QUEUE_WIDTH: gl.constexpr = 8, PRESORTED: gl.constexpr = False):
    pid = gl.program_id(0)
    if pid < M:
        meta_row = pid
        meta_keys = _route_keys(Keys, meta_row, NW, M, RSPLIT, KEY_PACK, KEY_BUFFER)
        route_layout: gl.constexpr = gl.BlockedLayout([1], [64], [NW], [0])
        slots = gl.arange(0, 16, route_layout)
        selected_keys = gl.full((16,), 0, gl.uint32, route_layout)
        meta_queue = _sorted_queue(meta_keys, KEY_PACK, PRESORTED=PRESORTED)
        for slot in gl.static_range(10):
            meta_winner, meta_queue = _pop_queue(meta_queue)
            selected_keys = gl.where(slots == slot, meta_winner, selected_keys)
        selected = gl.where(slots < 10, _decode_logit(selected_keys), -float('inf'))
        selected_ids = gl.where(slots == 10, 512, 511 - (selected_keys & 511))
        gl.store(Ids + meta_row * 11 + slots, selected_ids, slots < 11)
        p = gl.exp(selected - gl.max(selected, 0))
        p = p / gl.sum(p, 0)
        p = gl.where(slots == 10, gl.load(Shared + meta_row), p)
        gl.store(Probs + meta_row * 11 + slots, p, slots < 11)
    else:
        work = pid - M
        if M == 2:
            tile = (work // M) % (256 // BN)
            row = work % M
            rank = work // (M * (256 // BN))
        else:
            tile = work % (256 // BN)
            route_order = work // (256 // BN)
            row = route_order % M
            rank = route_order // M
        if M == 4:
            rank = (rank + 6) % 11
        elif REVERSE_RANK:
            rank = 10 - rank
        route = row * 11 + rank
        if PREFETCH:
            early_mma: gl.constexpr = gl.amd.AMDMFMALayout(
                version=4, instr_shape=[16, 16, 128], transposed=True,
                warps_per_cta=[NW, 1], tiles_per_warp=[BN // 16, 1])
            early_q_layout: gl.constexpr = gl.DotOperandLayout(1, early_mma, 16)
            early_g = gl.arange(0, 16, gl.SliceLayout(0, early_q_layout))
            early_k = gl.arange(0, 128, gl.SliceLayout(1, early_q_layout))
            if Q_BUFFER:
                q = gl.amd.cdna4.buffer_load(Q, row * 2048 + early_g[None, :] * 128 + early_k[:, None])
            else:
                q = gl.load(Q + row * 2048 + early_g[None, :] * 128 + early_k[:, None])
        expert = 512
        if rank < 10:
            keys = _route_keys(Keys, row, NW, M, RSPLIT, KEY_PACK, KEY_BUFFER)
            selected_key = _select_route_key(keys, rank, EARLY, KEY_PACK, TOPK_UNROLL, QUEUE_WIDTH, PRESORTED)
            expert = (511 - (selected_key & 511)).to(gl.int32)
        if M == 16:
            # Address the physical preshuffle directly in the MFMA A layout.
            mma_load: gl.constexpr = gl.amd.AMDMFMALayout(
                version=4, instr_shape=[16, 16, 128], transposed=True,
                warps_per_cta=[NW, 1], tiles_per_warp=[BN // 16, 1])
            load_layout: gl.constexpr = gl.DotOperandLayout(0, mma_load, 16)
            folded_row = gl.arange(0, 16 * BN, gl.SliceLayout(1, load_layout))
            input_k = gl.arange(0, 128, gl.SliceLayout(0, load_layout))
            if FUSE_ACT:
                output_n = ((folded_row % BN) // 8) * 128 + tile * 8 + folded_row % 8
            else:
                output_n = tile * BN + folded_row % BN
            group_k = folded_row // BN
            offsets = (expert * 524288 + (output_n[:, None] // 16) * 32768
                       + group_k[:, None] * 2048 + (input_k[None, :] // 16) * 256
                       + (output_n[:, None] % 16) * 16 + input_k[None, :] % 16)
            if BUFFER:
                weight = gl.amd.cdna4.buffer_load(W, offsets)
            else:
                weight = gl.load(W + offsets)
            weight = weight.reshape((16, BN, 128))
        else:
            physical_layout: gl.constexpr = gl.BlockedLayout([1, 16], [1, 64], [NW, 1], [1, 0])
            blocks = gl.arange(0, 16 * (BN // 16), gl.SliceLayout(1, physical_layout))
            byte = gl.arange(0, 2048, gl.SliceLayout(0, physical_layout))
            if FUSE_ACT:
                gl.static_assert(BN == 16)
                offsets = (expert * 524288 + (tile // 2) * 32768
                           + blocks[:, None] * 2048 + byte[None, :]
                           + ((byte[None, :] // 128) % 2) * (262144 - 128)
                           + (tile % 2) * 128)
            else:
                offsets = (expert * 524288 + (tile * (BN // 16) + blocks[:, None] // 16) * 32768
                           + (blocks[:, None] % 16) * 2048 + byte[None, :])
            if BUFFER:
                physical = gl.amd.cdna4.buffer_load(W, offsets)
            else:
                physical = gl.load(W + offsets)
            weight = physical.reshape((BN // 16, 16, 8, 16, 16)).permute((1, 0, 3, 2, 4)).reshape((16, BN, 128))
        if not PREFETCH:
            mma: gl.constexpr = gl.amd.AMDMFMALayout(
                version=4, instr_shape=[16, 16, 128], transposed=True,
                warps_per_cta=[NW, 1], tiles_per_warp=[BN // 16, 1])
            q_layout: gl.constexpr = gl.DotOperandLayout(1, mma, 16)
            qg = gl.arange(0, 16, gl.SliceLayout(0, q_layout))
            qk = gl.arange(0, 128, gl.SliceLayout(1, q_layout))
            q = gl.load(Q + row * 2048 + qg[None, :] * 128 + qk[:, None])
        sums = _folded_fp8_dot(weight, q, BN, NW).trans()
        out_layout: gl.constexpr = gl.BlockedLayout([1, 1], [64, 1], [NW, 1], [0, 1])
        sums = gl.convert_layout(sums, out_layout)
        on = tile * BN + gl.arange(0, BN, gl.SliceLayout(1, out_layout))
        if FUSE_ACT:
            pair_layout: gl.constexpr = gl.BlockedLayout([1, 1], [2, 32], [NW, 1], [1, 0])
            pair = gl.arange(0, 2, gl.SliceLayout(1, pair_layout))
            kg = gl.arange(0, 16, gl.SliceLayout(0, pair_layout))
            hs = gl.load(QS + row * 16 + kg)
            ws = gl.load(WS + expert * 32 + pair[:, None] * 16 + kg[None, :])
            compact = hs[None, :] * ws
            spread_layout: gl.constexpr = gl.BlockedLayout([1, 1, 1], [8, 8, 1], [NW, 1, 1], [1, 0, 2])
            compact = gl.convert_layout(compact, gl.SliceLayout(1, spread_layout))
            scales, _ = gl.broadcast(compact[:, None, :], gl.zeros((2, 8, 16), gl.float32, spread_layout))
            scales = gl.convert_layout(scales.reshape((16, 16)), out_layout)
        else:
            scale_layout: gl.constexpr = gl.BlockedLayout([1], [64], [NW], [0])
            sg = gl.arange(0, 16, scale_layout)
            hs_vector = gl.load(QS + row * 16 + sg)
            ws_vector = gl.load(WS + expert * 32 + (tile * BN // 128) * 16 + sg)
            scale_product = hs_vector * ws_vector
            scale_vector = gl.convert_layout(scale_product, gl.SliceLayout(0, out_layout))
            scales, _ = gl.broadcast(scale_vector[None, :], gl.zeros((BN, 16), gl.float32, out_layout))
        value = gl.fma(_column(sums, 0), _column(scales, 0), 0.0)
        for group in gl.static_range(1, 16):
            value = gl.fma(_column(sums, group), _column(scales, group), value)
        value = gl.convert_layout(value, gl.SliceLayout(1, out_layout))
        if FUSE_ACT:
            pair_out_layout: gl.constexpr = gl.BlockedLayout([1, 2], [64, 1], [NW, 1], [0, 1])
            pair_values = gl.convert_layout(value.reshape((2, 8)).trans(), pair_out_layout).to(gl.bfloat16)
            gate, up = gl.split(pair_values.to(gl.float32))
            silu = (gate * _sigmoid(gate)).to(gl.bfloat16).to(gl.float32)
            activation = (silu * up).to(gl.bfloat16)
            channel = tile * 8 + gl.arange(0, 8, activation.type.layout)
            gl.store(Packed + route * 128 + channel, activation)
        else:
            gl.store(Packed + route * 256 + on, value.to(gl.bfloat16))


@gluon.jit
def _load_down_weight(W, expert, tile, BN: gl.constexpr, NW: gl.constexpr,
                      BUFFER: gl.constexpr, W2_CACHE: gl.constexpr,
                      DIRECT: gl.constexpr = False):
    if DIRECT:
        # Physical block order: [output//16, input//16, output%16, input%16].
        mma: gl.constexpr = gl.amd.AMDMFMALayout(
            version=4, instr_shape=[16, 16, 32], transposed=True,
            warps_per_cta=[NW, 1, 1])
        layout: gl.constexpr = gl.DotOperandLayout(0, mma, 16)
        s = gl.arange(0, 16, gl.SliceLayout(1, gl.SliceLayout(2, layout)))
        n = tile * BN + gl.arange(0, BN, gl.SliceLayout(0, gl.SliceLayout(2, layout)))
        k = gl.arange(0, 128, gl.SliceLayout(0, gl.SliceLayout(1, layout)))
        e = gl.convert_layout(expert, s.type.layout)
        offsets = (e[:, None, None] * 262144 + (n[None, :, None] // 16) * 2048
                   + (k[None, None, :] // 16) * 256
                   + (n[None, :, None] % 16) * 16 + k[None, None, :] % 16)
        if BUFFER:
            return gl.amd.cdna4.buffer_load(W, offsets, s[:, None, None] < 11, other=0.0)
        else:
            return gl.load(W + offsets, s[:, None, None] < 11, other=0.0, cache_modifier=W2_CACHE)
    else:
        physical_layout: gl.constexpr = gl.BlockedLayout([1, 1, 16], [1, 1, 64], [NW, 1, 1], [2, 1, 0])
        ps = gl.arange(0, 16, gl.SliceLayout(1, gl.SliceLayout(2, physical_layout)))
        pn = tile * (BN // 16) + gl.arange(0, BN // 16, gl.SliceLayout(0, gl.SliceLayout(2, physical_layout)))
        pb = gl.arange(0, 2048, gl.SliceLayout(0, gl.SliceLayout(1, physical_layout)))
        pe = gl.convert_layout(expert, ps.type.layout)
        offsets = pe[:, None, None] * 262144 + pn[None, :, None] * 2048 + pb[None, None, :]
        if BUFFER:
            physical = gl.amd.cdna4.buffer_load(W, offsets, ps[:, None, None] < 11, other=0.0)
        else:
            physical = gl.load(W + offsets, ps[:, None, None] < 11, other=0.0, cache_modifier=W2_CACHE)
        return physical.reshape((16, BN // 16, 8, 16, 16)).permute((0, 1, 3, 2, 4)).reshape((16, BN, 128))


@gluon.jit
def _finish(Packed, Ids, Probs, W, WS, Output,
            BN: gl.constexpr, NW: gl.constexpr,
            BUFFER: gl.constexpr, TILE_GROUP: gl.constexpr,
            ROWS: gl.constexpr,
            W2_CACHE: gl.constexpr = "", NATIVE_LAYOUT: gl.constexpr = False,
            PREFETCH_WEIGHT: gl.constexpr = False, FUSE_ACT: gl.constexpr = False,
            UNSIGNED_INDEX: gl.constexpr = False, MASK_INDEX: gl.constexpr = False,
            FAST_EXP: gl.constexpr = False, QUANT_REFINE: gl.constexpr = True,
            BF16_EXCHANGE: gl.constexpr = False, LINEAR_GRID: gl.constexpr = False,
            DIRECT_WEIGHT: gl.constexpr = False):
    gl.static_assert((2048 // BN) % TILE_GROUP == 0)
    if TILE_GROUP == 1:
        if LINEAR_GRID:
            row = gl.program_id(0) % ROWS
            tile = gl.program_id(0) // ROWS
        else:
            row = 0 if ROWS == 1 else gl.program_id(0)
            tile = gl.program_id(1)
    else:
        linear = gl.program_id(0) if LINEAR_GRID else gl.program_id(0) + gl.program_id(1) * ROWS
        if UNSIGNED_INDEX:
            linear = linear.to(gl.uint32)
        if MASK_INDEX:
            gl.static_assert(TILE_GROUP == 8 and ROWS == 8)
            row = (linear >> 3) & 7
            tile = (linear >> 6) * 8 + (linear & 7)
        else:
            row = (linear // TILE_GROUP) % ROWS
            tile = (linear // (TILE_GROUP * ROWS)) * TILE_GROUP + linear % TILE_GROUP
    activation_pack: gl.constexpr = 1 if ROWS == 16 else 2
    activation_layout: gl.constexpr = gl.BlockedLayout([1, activation_pack], [1, 64], [NW, 1], [1, 0])
    slot = gl.arange(0, 16, gl.SliceLayout(1, activation_layout))
    k = gl.arange(0, 128, gl.SliceLayout(0, activation_layout))
    route = row * 11 + gl.minimum(slot, 10)
    expert = gl.load(Ids + route)
    probability = gl.load(Probs + route)
    if PREFETCH_WEIGHT:
        weight = _load_down_weight(W, expert, tile, BN, NW, BUFFER, W2_CACHE, DIRECT_WEIGHT)
    if FUSE_ACT:
        act = gl.load(Packed + route[:, None] * 128 + k[None, :]).to(gl.float32)
    else:
        gate = gl.load(Packed + route[:, None] * 256 + k[None, :]).to(gl.float32)
        up = gl.load(Packed + route[:, None] * 256 + 128 + k[None, :]).to(gl.float32)
        silu = (gate * _sigmoid(gate, FAST_EXP)).to(gl.bfloat16).to(gl.float32)
        act = (silu * up).to(gl.bfloat16).to(gl.float32)
    scale = gl.maximum(gl.max(gl.abs(act), 1), 1.0e-10) / 448.0
    q = _divide(act, scale[:, None], QUANT_REFINE).to(gl.float8e4nv)
    if not PREFETCH_WEIGHT:
        weight = _load_down_weight(W, expert, tile, BN, NW, BUFFER, W2_CACHE, DIRECT_WEIGHT)
    sums = _native_fp8_dot(weight, q, BN, NW)
    if NATIVE_LAYOUT:
        value_layout: gl.constexpr = sums.type.layout
    else:
        value_layout: gl.constexpr = gl.BlockedLayout([1, 1], [1, 64], [NW, 1], [1, 0])
    dots = gl.convert_layout(sums, value_layout)
    vn = tile * BN + gl.arange(0, BN, gl.SliceLayout(0, value_layout))
    ve = gl.convert_layout(expert, gl.SliceLayout(1, value_layout))
    vs = gl.convert_layout(scale, gl.SliceLayout(1, value_layout))
    vp = gl.convert_layout(probability, gl.SliceLayout(1, value_layout))
    ws = gl.load(WS + ve[:, None] * 16 + vn[None, :] // 128)
    # Round each contribution before transport and ordered route addition.
    contribution = (dots * (vs[:, None] * ws) * vp[:, None]).to(gl.bfloat16)
    if ROWS != 16 and not BF16_EXCHANGE:
        contribution = contribution.to(gl.float32)
    local_layout: gl.constexpr = gl.BlockedLayout([1, 1], [64, 1], [NW, 1], [0, 1])
    local = gl.convert_layout(contribution.trans(), local_layout).to(gl.float32)
    total = 0.0 + _column(local, 0)
    for i in gl.static_range(1, 11):
        total = total + _column(local, i)
    on = tile * BN + gl.arange(0, BN, total.type.layout)
    gl.store(Output + row * 2048 + on, total.to(gl.bfloat16))


def qwen_router_complete_moe(
    hidden_states: torch.Tensor,
    router_weight: torch.Tensor,
    w13: torch.Tensor,
    w2: torch.Tensor,
    w13_scales: torch.Tensor,
    w2_scales: torch.Tensor,
    shared_gate_weight: torch.Tensor,
    *,
    group_n: int = 128,
    group_k: int = 128,
    precision_config=_PrecisionConfig(),
    out: torch.Tensor,
) -> torch.Tensor:
    """Compute the registered 1/2/4/8/16-token E4M3FN decode cases."""
    rows, width = hidden_states.shape
    assert rows in (1, 2, 4, 8, 16) and width == 2048
    assert group_n == group_k == 128
    assert w13.shape == (513, 256, 2048)
    assert w2.shape == (513, 2048, 128)
    assert w13_scales.shape == (513, 2, 16)
    assert w2_scales.shape == (513, 16, 1)
    assert router_weight.shape == (512, 2048)
    assert shared_gate_weight.shape == (1, 2048)
    assert hidden_states.dtype == router_weight.dtype == torch.bfloat16
    assert shared_gate_weight.dtype == torch.bfloat16
    assert w13.dtype == w2.dtype == precision_config.dtype == torch.float8_e4m3fn
    assert w13_scales.dtype == w2_scales.dtype == torch.float32
    device = hidden_states.device
    for tensor in (hidden_states, router_weight, w13, w2, w13_scales, w2_scales, shared_gate_weight):
        assert tensor.device == device and tensor.is_contiguous()
    router_split = 4 if rows == 16 else 1
    router_n = 8 if rows in (4, 16) else 4
    router_warps = 2 if rows >= 8 else 4
    router_ctas = (router_split if router_split > 1 else rows) * (512 // router_n)
    keys = torch.empty(
        (router_split, rows, 512),
        dtype=torch.float32 if router_split > 1 else torch.int32, device=device)
    quantized = torch.empty((rows, 2048), dtype=w13.dtype, device=device)
    scales = torch.empty((rows, 16), dtype=torch.float32, device=device)
    shared = torch.empty((rows,), dtype=torch.float32, device=device)
    packed = torch.empty((rows * 11, 128 if rows <= 2 else 256), dtype=torch.bfloat16, device=device)
    ids = torch.empty((rows, 11), dtype=torch.int32, device=device)
    probs = torch.empty((rows, 11), dtype=torch.float32, device=device)
    output = out
    _prepare[(router_ctas + 2 * rows,)](
        hidden_states, router_weight, shared_gate_weight, keys,
        quantized, scales, shared, rows, router_n, router_warps, router_split,
        num_warps=router_warps, enable_fp_fusion=False,
        PREP_FIRST=rows >= 4, GATE_FIRST=rows == 2,
        QUANT_LANES=64 if rows == 4 else (32 if rows == 16 else 16),
        GATE_GROUPS=rows in (2, 4), SORT_KEYS=rows <= 2,
        UNSIGNED_PID=rows in (2, 4), ROUTER_BUFFER=rows == 8)
    project_n = 16
    project_warps = 1
    project_buffer = rows in (8, 16)
    early_ranks = 6 if rows == 1 else (4 if rows == 2 else (3 if rows == 4 else (0 if rows == 8 else 1)))
    _project[(rows + rows * 11 * (256 // project_n),)](
        keys, quantized, scales, shared, w13, w13_scales, packed, ids, probs,
        rows, project_n, project_warps, router_split, project_buffer, early_ranks,
        KEY_PACK=4 if rows == 1 else 8, PREFETCH=rows <= 8,
        REVERSE_RANK=rows in (2, 4),
        KEY_BUFFER=rows <= 2, Q_BUFFER=rows == 2, FUSE_ACT=rows <= 2,
        TOPK_UNROLL=8 if rows <= 2 else (4 if rows == 4 else 0),
        QUEUE_WIDTH=4 if rows == 8 else 8, PRESORTED=rows <= 2,
        num_warps=project_warps, waves_per_eu=6 if rows == 16 else 0,
        llvm_fn_attrs=[["amdgpu-sched-strategy",
                        "max-memory-clause" if rows == 16 else "max-ilp"]])
    finish_n = 64 if rows == 16 else (16 if rows <= 2 else 32)
    finish_group = 8 if rows >= 4 else (4 if rows == 2 else 1)
    finish_grid = (rows * (2048 // finish_n),) if rows == 2 else (rows, 2048 // finish_n)
    _finish[finish_grid](
        packed, ids, probs, w2, w2_scales, output, finish_n, 8, BUFFER=rows <= 2,
        TILE_GROUP=finish_group, ROWS=rows, num_warps=8, enable_fp_fusion=False,
        waves_per_eu=4 if rows == 1 else (3 if rows == 4 else 0),
        W2_CACHE=".cg" if rows in (4, 8) else "", NATIVE_LAYOUT=rows in (1, 2, 16),
        PREFETCH_WEIGHT=rows <= 2, FUSE_ACT=rows <= 2,
        UNSIGNED_INDEX=rows in (2, 4), MASK_INDEX=rows == 8, FAST_EXP=rows >= 4,
        QUANT_REFINE=rows not in (2, 4),
        BF16_EXCHANGE=rows == 8, LINEAR_GRID=rows == 2,
        DIRECT_WEIGHT=rows == 4,
        llvm_fn_attrs=([["amdgpu-sched-strategy", "max-memory-clause"]] if rows == 4
                       else ([["amdgpu-sched-strategy", "max-ilp"]] if rows >= 8 else [])))
    return output


def run(
    *,
    hidden_states,
    router_weight,
    shared_gate_weight,
    w1,
    w1_scale,
    w2,
    w2_scale,
    topk,
    out_dtype,
    out,
):
    """The router, the routed experts and the gated shared expert of ``hidden_states``
    into ``out``."""
    qwen_router_complete_moe(
        hidden_states,
        router_weight,
        w1,
        w2,
        w1_scale,
        w2_scale,
        shared_gate_weight,
        out=out,
    )
